use super::*;

/// Decide one tick against a caller's baseline.
///
/// `seen` is how many lines the caller has already accounted for, or NEGATIVE for "not yet
/// baselined". Both of those cases, and a log that SHRANK (rotated, replaced, or the window slid past
/// what the caller had seen), voice nothing and just re-baseline — never voice the backlog. That rule
/// is why the count comes back with the cues: the caller cannot compute it without the lines, and
/// shipping the lines to the caller is the thing this exists to stop.
pub fn notify_tick(lines: &[String], seen: i64) -> NotifyTick {
    let total = lines.len();
    if seen < 0 || seen as usize > total {
        return NotifyTick { total, cues: Vec::new() };
    }
    NotifyTick { total, cues: cues_for_lines(&lines[seen as usize..]) }
}
